package com.bankingax.task.c02;
import static org.junit.jupiter.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test;
class C02PowerOfAttorneyOcrComparisonTest {
 private final C02PowerOfAttorneyOcrComparison.CaseFacts facts=new C02PowerOfAttorneyOcrComparison.CaseFacts(77,4,99,"김 영준",List.of("김민수"),List.of("김하나"));
 private C02PowerOfAttorneyOcrComparison.OcrDocument doc(String agent,List<C02PowerOfAttorneyOcrComparison.Person> ds,String status){return new C02PowerOfAttorneyOcrComparison.OcrDocument("김영준",List.of(new C02PowerOfAttorneyOcrComparison.Account("99900000000001")),new C02PowerOfAttorneyOcrComparison.Person(agent),ds,status);}
 @Test void matches_three_names_but_requires_staff_for_account(){var r=C02PowerOfAttorneyOcrComparison.compare(facts,doc("김민수",List.of(new C02PowerOfAttorneyOcrComparison.Person("김하나")),"SUCCEEDED"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.AUTO_MATCHED,r.fields().get(0).outcome());assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.STAFF_REQUIRED,r.fields().get(3).outcome());}
 @Test void rejects_agent_mismatch_missing_delegator_and_failure(){assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.MISMATCH,C02PowerOfAttorneyOcrComparison.compare(facts,doc("다른이름",List.of(new C02PowerOfAttorneyOcrComparison.Person("김하나")),"SUCCEEDED")).fields().get(1).outcome());assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.STAFF_REQUIRED,C02PowerOfAttorneyOcrComparison.compare(facts,doc("김민수",List.of(),"SUCCEEDED")).fields().get(2).outcome());assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.OCR_UNSUPPORTED,C02PowerOfAttorneyOcrComparison.compare(facts,doc("김민수",List.of(),"FAILED")).fields().get(0).outcome());}
 private static final C02PowerOfAttorneyOcrComparison.CaseFacts BIRTH_FACTS=new C02PowerOfAttorneyOcrComparison.CaseFacts(77,4,99,"김영준","1955-01-01",List.of("김민수"),List.of("김하나"),Map.of("김민수","1997-04-12","김하나","1994-01-03"));
 private static C02PowerOfAttorneyOcrComparison.OcrDocument births(String depositor,String agent,String delegator){return new C02PowerOfAttorneyOcrComparison.OcrDocument("김영준",depositor,List.of(new C02PowerOfAttorneyOcrComparison.Account("99900000000001")),new C02PowerOfAttorneyOcrComparison.Person("김민수",agent),List.of(new C02PowerOfAttorneyOcrComparison.Person("김하나",delegator)),"SUCCEEDED");}
 private static C02PowerOfAttorneyOcrComparison.Outcome outcome(C02PowerOfAttorneyOcrComparison.Comparison comparison,String field){return comparison.fields().stream().filter(row->row.field().equals(field)).findFirst().orElseThrow().outcome();}
 @Test void birth_dates_match_across_stored_formats(){var r=C02PowerOfAttorneyOcrComparison.compare(BIRTH_FACTS,births("19550101","19970412","940103"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.AUTO_MATCHED,outcome(r,"depositorBirthDate"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.AUTO_MATCHED,outcome(r,"agent.birthDate"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.AUTO_MATCHED,outcome(r,"delegators[0].birthDate"));}
 @Test void a_different_birth_date_is_a_mismatch(){var r=C02PowerOfAttorneyOcrComparison.compare(BIRTH_FACTS,births("19580211","19970413","19940103"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.MISMATCH,outcome(r,"depositorBirthDate"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.MISMATCH,outcome(r,"agent.birthDate"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.AUTO_MATCHED,outcome(r,"delegators[0].birthDate"));}
 @Test void a_missing_birth_date_goes_to_staff_and_is_never_a_match(){var r=C02PowerOfAttorneyOcrComparison.compare(BIRTH_FACTS,births("","19970412",null));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.STAFF_REQUIRED,outcome(r,"depositorBirthDate"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.STAFF_REQUIRED,outcome(r,"delegators[0].birthDate"));}
 @Test void a_name_without_a_case_birth_date_goes_to_staff(){var noBirth=new C02PowerOfAttorneyOcrComparison.CaseFacts(77,4,99,"김영준",null,List.of("김민수"),List.of("김하나"),Map.of());var r=C02PowerOfAttorneyOcrComparison.compare(noBirth,births("19550101","19970412","19940103"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.STAFF_REQUIRED,outcome(r,"depositorBirthDate"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.STAFF_REQUIRED,outcome(r,"agent.birthDate"));}
 @Test void handles_multiple_delegators_without_guessing(){var r=C02PowerOfAttorneyOcrComparison.compare(facts,doc("김민수",List.of(new C02PowerOfAttorneyOcrComparison.Person("김하나"),new C02PowerOfAttorneyOcrComparison.Person("추가인")),"SUCCEEDED"));assertEquals(C02PowerOfAttorneyOcrComparison.Outcome.MISMATCH,r.fields().get(2).outcome());assertEquals(77,r.caseId());assertEquals(4,r.revision());assertEquals(99,r.documentFileId());}
}
